const readSetupScript = (): string => {
  const config = fs.readFileSync(setupConfigPath, 'utf8');
  const scriptMatch = /\[setup\]\nscript = '''\n([\s\S]*?)\n'''/.exec(config);

  if (!scriptMatch) {
    throw new Error('Missing setup script in Codex environment config');
