import { describe, expect, it } from '@effect/vitest';
import { execFileSync, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repositoryRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
  '..',
);
const setupFiles = [
  '.codex/environments/environment.toml',
  '.codex/environments/setup.sh',
  'helpers/setup-worktree.sh',
  't3.json',
];

const readCodexCommand = (cwd: string): string => {
  const config = fs.readFileSync(
    path.join(cwd, '.codex/environments/environment.toml'),
    'utf8',
  );
  const command = /^script = "([^"]+)"$/m.exec(config)?.[1];
  if (!command) throw new Error('Missing Codex setup command');
  return command;
};

const readT3Command = (cwd: string): string => {
  const config: {
    scripts: { command: string; runOnWorktreeCreate: boolean }[];
  } = JSON.parse(fs.readFileSync(path.join(cwd, 't3.json'), 'utf8'));
  const command = config.scripts.find(
    (script) => script.runOnWorktreeCreate,
  )?.command;
  if (!command) throw new Error('Missing T3 Code worktree setup command');
  return command;
};

const testEnvironment = Object.fromEntries(
  Object.entries(process.env).filter(
    ([name]) =>
      name !== 'CODEX_SOURCE_ROOT' &&
      name !== 'FONT_AWESOME_TOKEN' &&
      !name.startsWith('GIT_'),
  ),
);
const gitEnvironment = {
  ...testEnvironment,
  GIT_CONFIG_GLOBAL: os.devNull,
  GIT_CONFIG_NOSYSTEM: '1',
};

const runGit = (cwd: string, ...commandArguments: readonly string[]): string =>
  execFileSync(
    'git',
    ['-c', `core.hooksPath=${os.devNull}`, ...commandArguments],
    {
      cwd,
      encoding: 'utf8',
      env: gitEnvironment,
    },
  );

const createFixture = () => {
  const fixtureRoot = fs.mkdtempSync(
    path.join(os.tmpdir(), 'evorto env setup '),
  );

  try {
    const mainCheckout = path.join(
      fixtureRoot,
      'main checkout\nwith a newline',
    );
    const worktree = path.join(fixtureRoot, 'linked worktree');
    const stubBin = path.join(fixtureRoot, 'stub bin');

    fs.mkdirSync(mainCheckout);
    fs.mkdirSync(stubBin);
    fs.writeFileSync(path.join(mainCheckout, '.gitignore'), '.env*\n');
    fs.writeFileSync(path.join(mainCheckout, 'tracked.txt'), 'fixture\n');

    for (const file of setupFiles) {
      const destination = path.join(mainCheckout, file);
      fs.mkdirSync(path.dirname(destination), { recursive: true });
      fs.copyFileSync(path.join(repositoryRoot, file), destination);
    }

    runGit(mainCheckout, 'init', '--initial-branch=main');
    runGit(mainCheckout, 'config', 'user.email', 'codex@example.test');
    runGit(mainCheckout, 'config', 'user.name', 'Codex Test');
    runGit(mainCheckout, 'add', '.');
    runGit(mainCheckout, 'commit', '--no-gpg-sign', '-m', 'Create fixture');
    runGit(mainCheckout, 'worktree', 'add', '-b', 'fixture-worktree', worktree);
    runGit(mainCheckout, 'remote', 'add', 'origin', mainCheckout);

    const bunStub = path.join(stubBin, 'bun');
    fs.writeFileSync(
      bunStub,
      '#!/bin/sh\ncase " $* " in\n  *" -e "*) PATH="$SETUP_ORIGINAL_PATH" exec bun "$@" ;;\nesac\nprintf "%s\n" "$*"\n',
    );
    fs.chmodSync(bunStub, 0o755);

    return {
      fixtureRoot,
      mainCheckout,
      runSetup: (
        cwd = worktree,
        tool: 'codex' | 't3' = 'codex',
        token = 'fixture-token',
      ) => {
        const environment = {
          ...gitEnvironment,
          ...(token ? { FONT_AWESOME_TOKEN: token } : {}),
          SETUP_ORIGINAL_PATH: process.env['PATH'] ?? '',
          ...(tool === 't3'
            ? {
                T3CODE_PROJECT_ROOT: mainCheckout,
                T3CODE_WORKTREE_PATH: worktree,
              }
            : {}),
          PATH: `${stubBin}${path.delimiter}${process.env['PATH'] ?? ''}`,
        };

        const command =
          tool === 't3' ? readT3Command(cwd) : readCodexCommand(cwd);
        const result = spawnSync('bash', ['-c', command], {
          cwd,
          encoding: 'utf8',
          env: environment,
        });

        if (result.error) {
          throw result.error;
        }
        if (result.status !== 0) {
          throw new Error(
            `Setup failed with status ${result.status}: ${result.stderr}`,
          );
        }

        return {
          stderr: result.stderr,
          stdout: result.stdout,
        };
      },
      worktree,
    };
  } catch (error) {
    fs.rmSync(fixtureRoot, { force: true, recursive: true });
    throw error;
  }
};

#!/usr/bin/env bash
set -euo pipefail

MAIN_CHECKOUT_WITH_SENTINEL=$(
  git worktree list --porcelain -z |
    perl -0ne 'if (!$found && /^worktree /) { chomp; s/^worktree //; print "$_."; $found = 1 }'
)
MAIN_CHECKOUT=${MAIN_CHECKOUT_WITH_SENTINEL%?}
if [ -n "$MAIN_CHECKOUT" ] && [ "$(pwd -P)" != "$MAIN_CHECKOUT" ] && [ ! -e .env ] && [ ! -L .env ] && [ -f "$MAIN_CHECKOUT/.env" ]; then
  (
    umask 077
    ENV_TEMP=$(mktemp .env.tmp.XXXXXX)
    trap 'rm -f "$ENV_TEMP"' EXIT
    cp "$MAIN_CHECKOUT/.env" "$ENV_TEMP"
    chmod 600 "$ENV_TEMP"
    if ln "$ENV_TEMP" .env 2>/dev/null; then
      echo "[setup] Copied .env from the main checkout."
    elif [ ! -e .env ] && [ ! -L .env ]; then
      echo "[setup] Could not publish .env in the new worktree." >&2
      exit 1
    fi
  )
fi

# Use the developer dotenv file for registry access, with exported values taking precedence.
bun_env=(--no-env-file)
if [ -f .env ]; then
  bun_env+=(--env-file=.env)
fi

if ! bun "${bun_env[@]}" -e 'process.exit(process.env.FONT_AWESOME_TOKEN?.trim() ? 0 : 1)'; then
  echo "[setup] Set FONT_AWESOME_TOKEN in .env or export it to install private Font Awesome packages." >&2
  exit 1
fi

echo "[setup] Installing dependencies (bun install)"
perl -e 'alarm shift; exec @ARGV' 240 bun install "${bun_env[@]}" --frozen-lockfile --network-concurrency 12

echo "[setup] Generating runtime environment"
bun --no-env-file helpers/testing/runtime-environment.ts
